let priceItem=document.querySelectorAll(".price__item"),btnMore=(priceItem.forEach(t=>{t.addEventListener("click",function(e){priceItem.forEach(e=>{e.classList.remove("price__item--active")}),t.classList.add("price__item--active")})}),document.querySelectorAll(".more__button"));btnMore.forEach(i=>{i.addEventListener("click",function(e){e.preventDefault();let t=this.nextElementSibling;e=t.querySelector(".more__hide");t.style.maxHeight=t.scrollHeight+"px",i.style.display="none",e.addEventListener("click",function(){t.style.maxHeight=null,i.style.display="block"})})});